export const externalPlateRegionSources={"Germany":{"url":"https://raw.githubusercontent.com/openpotato/kfz-kennzeichen/main/src/de/kennzeichen.csv","kind":"csv","column":2,"skip":1},"Austria":{"url":"https://raw.githubusercontent.com/openpotato/kfz-kennzeichen/main/src/at/kennzeichen.csv","kind":"csv","column":2,"skip":1},"Poland":{"url":"https://raw.githubusercontent.com/open-admin-data/poland-administrative-divisions/master/data/all-county.json","kind":"poland-counties"}};


function parseCsvLine(line){
  const out=[]; let cur="",quoted=false;
  for(let i=0;i<line.length;i++){
    const ch=line[i];
    if(ch==='"'){
      if(quoted&&line[i+1]==='"'){cur+='"';i++;}else quoted=!quoted;
    }else if(ch===','&&!quoted){out.push(cur);cur="";}else cur+=ch;
  }
  out.push(cur); return out;
}

export async function loadExternalPlateRegions(){
  const out={};
  await Promise.all(Object.entries(externalPlateRegionSources).map(async([country,src])=>{
    try{
      const response=await fetch(src.url,{cache:'force-cache'});
      if(!response.ok)throw new Error(`${response.status}`);
      if(src.kind==='csv'){
        const text=await response.text();
        const values=text.split(/\r?\n/).slice(src.skip||0).filter(Boolean).map(parseCsvLine).map(row=>(row[src.column]||'').trim()).filter(Boolean);
        out[country]=[...new Set(values)].sort((a,b)=>a.localeCompare(b));
      }else if(src.kind==='poland-counties'){
        const data=await response.json();
        const values=(Array.isArray(data)?data:[]).map(x=>x?.name?.en||x?.name?.local||x?.name).filter(x=>typeof x==='string'&&x.trim()).map(x=>x.trim());
        out[country]=[...new Set(values)].sort((a,b)=>a.localeCompare(b));
      }
    }catch(err){ console.warn(`PlateDex: could not load detailed regions for ${country}`,err); }
  }));
  return out;
}
